const { z } = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let out;
try { out = z.tuple([z.string(), z.string().default("bravo")]).parse(["alpha"]); }
catch (e) { broken("parse threw: " + e.message); }
if (!Array.isArray(out)) broken("parse returned " + JSON.stringify(out));
if (out.length === 1 && out[0] === "alpha") symptom("z.tuple ignored the default of the missing trailing element, parse returned only alpha");
if (out.length !== 2 || out[0] !== "alpha" || out[1] !== "bravo") broken("unexpected output " + JSON.stringify(out));
console.log("OK: z.tuple applied the default of the missing trailing element: " + JSON.stringify(out));

